import{t as e}from"./jsx-runtime-lw2jiZar.js";import{A as t,C as n,E as r,M as i,N as a,O as o,P as s,T as c,_ as l,j as u,k as d,l as f,n as p,o as m,t as h,v as g}from"./shared-DoR5oW6-.js";import{t as _}from"./wrench-BJLceorR.js";import{O as v}from"./index-ChLJS9_n.js";import{t as y}from"./CodeEditor-BZlrvoTL.js";var b=e();function x({module:e}){return(0,b.jsxs)(a,{children:[(0,b.jsx)(i,{variant:`project`,chip:e??`Блок 7 · Объектная модель`,title:`32.1. Метод и управляемое изменение`,intro:`Добавим к подготовленной Task методы для изменения одной задачи. Разберём, как вызов получает объект, почему проверка идёт до присваивания и как отказ сохраняет прежнее состояние.`,tags:[{icon:(0,b.jsx)(_,{size:14}),label:`методы модели`},{icon:(0,b.jsx)(v,{size:14}),label:`проверка до изменения`}]}),(0,b.jsxs)(s,{number:`00`,title:`Вступление`,children:[(0,b.jsx)(o,{children:`К проверенным полям той же Task добавим три действия и заранее определим их договор: корректный запрос меняет нужное поле, а ошибочный оставляет прежнее значение.`}),(0,b.jsx)(d,{variant:`connected`,items:[{title:`Точка старта`,description:`Task хранит проверенные id, title, priority и is_done; состояние разных экземпляров независимо.`},{title:`Новый вопрос`,description:`Как изменить одно поле конкретной задачи и оставить прежнее значение, если запрос неверен?`},{title:`Результат`,description:`Три метода управляют статусом, названием и приоритетом, пока CLI продолжает работать со словарями.`}]}),(0,b.jsx)(`p`,{children:`Сначала проследим путь вызова через конкретный объект. Затем разберём договор методов и поставим проверку нового значения перед присваиванием. На этом основании добавим действия в ту же Task и отдельно сверим старый путь приложения.`})]}),(0,b.jsxs)(s,{number:`01`,title:`Метод вызывается для конкретного экземпляра`,children:[(0,b.jsx)(o,{children:`Методом называют функцию, объявленную внутри класса и вызываемую через экземпляр этого класса. У метода есть текущий получатель: объект, перед точкой в выражении вызова. Поэтому task.rename("Новое название") относится к конкретной задаче task, а не ко всем задачам приложения.`}),(0,b.jsx)(`p`,{children:`При обычном вызове через точку Python сам передаёт объект первым аргументом метода. Если определение записано как set_target(self, value), то при вызове room.set_target(21) параметр self получает room, а value получает 21. В круглых скобках мы передаём только дополнительные аргументы. self не глобальное слово и не отдельная ссылка на список: это обычный параметр, которому язык передал текущий экземпляр.`}),(0,b.jsx)(`p`,{children:`Представим мастерскую с несколькими приборами. Запись room.set_target(21) похожа на заявку, адресованную одному выбранному прибору: room отвечает на вопрос, чей параметр меняется, а 21 задаёт новое значение. Сравнение помогает увидеть получателя и данные заявки. В Python нет отдельного мастера, который выбирает прибор за нас: получатель явно стоит перед точкой, а механизм вызова связывает его с self.`}),(0,b.jsx)(`p`,{children:`Внутри метода нужно отличать параметр вызова от состояния объекта. Имя value хранит вход только на время этого вызова. Поле self.target принадлежит экземпляру и останется у него после завершения метода. Даже если параметр называется так же, как поле, это всё ещё два разных имени и две разные роли. Именно присваивание через self изменяет состояние получателя.`}),(0,b.jsx)(g,{code:`class Thermostat:
    def __init__(self, target):
        self.target = target
    def set_target(self, value):
        self.target = value
room = Thermostat(18)
room.set_target(21)
print(room.target)`,steps:[{line:5,note:`Мы создаём один прибор. Его поле target получает 18.`,vars:{"room.target":`18`}},{line:6,note:`Вызов через точку передаёт room в self, а число 21 в value.`,vars:{self:`room`,value:`21`}},{line:4,note:`Метод записывает новое значение в поле того же экземпляра.`,vars:{"room.target":`21`}},{line:7,note:`Читаем изменённое поле. Подготовленный вывод равен 21.`,vars:{output:`21`}}]}),(0,b.jsx)(`p`,{children:`Это короткий самостоятельный пример только о том, как метод получает экземпляр. При вызове Thermostat.set_target(room, 21) объект можно передать вручную, но такой низкоуровневый вид не нужен в обычном коде. Связанный вызов через конкретный прибор яснее показывает, кому адресовано действие.`})]}),(0,b.jsxs)(s,{number:`02`,title:`Метод меняет состояние и отдельно обещает результат`,children:[(0,b.jsx)(o,{children:`Метод может прочитать поле, вычислить ответ или изменить состояние. Эти действия не означают одно и то же. Например, метод проверки возвращает bool, а команда изменения может обновить поле и ничего не возвращать. До вызова полезно понимать обе части договора: какой эффект произойдёт и какое значение придёт обратно.`}),(0,b.jsx)(`p`,{children:`В этом занятии mark_done, rename и set_priority изменяют свою задачу и возвращают None. None обозначает отсутствие полезного возвращаемого значения. Если метод заканчивается после присваивания и в нём нет return с выражением, Python всё равно возвращает None. Новое состояние мы читаем из полей того же объекта, а не получаем как новую Task.`}),(0,b.jsx)(`p`,{children:`Сравним действие с настенным выключателем. Команда «включить свет» устанавливает состояние во включённое; повтор той же команды оставляет его включённым. Это помогает отличить её от переключателя, который каждый раз меняет состояние на противоположное. Аналогия касается только повторяемого перехода, она не описывает все правила модели или поведение электроприбора.`}),(0,b.jsx)(`p`,{children:`Для mark_done мы используем такой же устойчивый договор: поле is_done становится настоящим True. Повторный вызов не создаёт новую задачу и не открывает уже завершённую. Это упрощает повторную обработку команды и делает наблюдаемый результат предсказуемым. Методы переименования и смены приоритета ведут себя иначе по полю, но также должны сохранять ясную связь между запросом, эффектом и результатом вызова.`}),(0,b.jsx)(l,{code:`class Meter:
    def __init__(self, value):
        self.value = value
    def add(self, amount):
        self.value += amount
meter = Meter(4)
result = meter.add(3)
print(meter.value, result)`,output:`7 None`,hint:`Проследим отдельно поле meter.value и значение, которое метод передал вызывающему коду.`}),(0,b.jsx)(`p`,{children:`Мы ожидаем увидеть 7 и None. Сначала метод меняет поле экземпляра с 4 на 7. Затем присваивание result получает возвращаемое значение вызова, а явного return в add нет. Изменение объекта не превращает результат метода в копию объекта. Поэтому в проектных проверках отдельно прочитаем новые поля и отдельно посмотрим на None.`}),(0,b.jsx)(`p`,{children:`Поле и результат вызова можно наблюдать независимо. В примере с Meter поле meter.value изменилось с 4 на 7, хотя переменная result получила None. Если забыть эту разницу, можно решить, что метод не сработал, или ожидать от него новую копию объекта. Поэтому мы читаем состояние получателя после вызова и отдельно проверяем возвращаемое значение. В текущей Task договор не обещает возвращать модель.`})]}),(0,b.jsxs)(s,{number:`03`,title:`Новое значение сначала проходит проверку`,children:[(0,b.jsx)(o,{children:`Перед сохранением нового значения мы проверяем, подходит ли оно правилам модели. Такое правило допустимого состояния часто называют инвариантом. Для Task допустимы только название после очистки пробелов и приоритет в согласованном диапазоне. Уже существующие валидаторы знают эти условия, поэтому методы будут пользоваться ими, а не поддерживать вторую копию правил.`}),(0,b.jsx)(`p`,{children:`validate_title принимает строку, очищает внешние пробелы и возвращает готовое название. Если после очистки оно пустое, валидатор поднимает ValueError. validate_priority возвращает число, если оно проходит правило типа и диапазона, иначе тоже сообщает об ошибке значения. Исключение останавливает текущий успешный путь и передаётся вызывающему коду; оно не становится молчаливым None и не означает, что поле изменено.`}),(0,b.jsx)(`p`,{children:`Проверка через общий валидатор оставляет единый договор: фабрика, конструктор и метод не расходятся в том, какое значение принимают. Здесь мы не пересматриваем правило и не превращаем метод в интерфейс ввода. Меняется только момент вызова уже подготовленной проверки, непосредственно перед присваиванием.`}),(0,b.jsx)(`p`,{children:`Порядок важен: сначала получаем проверенное значение во временное имя, после успешной проверки записываем его в поле. Пока проверка выполняется, старое поле не тронуто. Это похоже на замену таблички на двери: сначала мы готовим и проверяем новую надпись, затем заменяем старую. Аналогия объясняет последовательность действий, но не гарантирует, что все операции программы транзакционны или автоматически откатываются.`}),(0,b.jsx)(y,{caption:`независимый пример безопасного изменения регулятора`,code:`def validate_level(value):
    if not 0 <= value <= 10:
        raise ValueError("Уровень вне диапазона")
    return value

class Speaker:
    def __init__(self, level):
        self.level = validate_level(level)

    def set_level(self, new_level):
        checked_level = validate_level(new_level)
        self.level = checked_level`}),(0,b.jsx)(`p`,{children:`Здесь мы проверяем уровень громкости до записи. При корректном числе validate_level возвращает именно то значение, которое можно хранить. Если число не подходит, выполнение прерывается на валидаторе, а строка присваивания не достигается. Пример использует Speaker и уровень звука, поэтому он объясняет порядок, не создавая вторую Task и не заменяя практическое изменение модели.`}),(0,b.jsx)(h,{caption:`Путь корректного значения до поля объекта`,children:(0,b.jsxs)(m,{label:`Объект получает значение, проверяет его и сохраняет`,children:[(0,b.jsx)(f,{title:`Экземпляр Speaker`,children:(0,b.jsx)(`p`,{children:`Хранит своё поле level`})}),(0,b.jsx)(p,{label:`вызов метода`}),(0,b.jsx)(f,{title:`set_level(new_level)`,children:(0,b.jsx)(`p`,{children:`Получает новый запрос`})}),(0,b.jsx)(p,{label:`передаёт аргумент`}),(0,b.jsx)(f,{title:`validate_level`,children:(0,b.jsx)(`p`,{children:`Возвращает принятое значение`})}),(0,b.jsx)(p,{label:`если проверка успешна`}),(0,b.jsx)(f,{title:`self.level = checked_level`,children:(0,b.jsx)(`p`,{children:`Меняется только поле получателя`})})]})}),(0,b.jsx)(r,{tone:`info`,children:`Если validate_level поднимает ValueError, выполнение не доходит до присваивания self.level. Прежнее значение остаётся на объекте, потому что мы не записывали новый кандидат до проверки.`}),(0,b.jsx)(`p`,{children:`Проверка в модели нужна и при вызове не через CLI. Валидатор в reader защищает ручной ввод, но ту же модель могут вызвать из другого обработчика или короткого скрипта. Если единственная проверка живёт до модели, другой путь вызова способен пропустить её. Методы повторно используют общие функции правил и не зависят от того, кто передал значение. При этом решение о сообщении остаётся у вызывающего кода.`}),(0,b.jsx)(`p`,{children:`Следующие пары строк показаны как фрагменты тела метода, а не как готовые отдельные функции. Сравним, какой порядок сохранит принятое состояние.`}),(0,b.jsx)(c,{question:`Какой порядок сохраняет прежнее значение при отказе валидатора?`,left:{title:`Проверить и присвоить`,code:`checked = validate(value)
self.level = checked`,note:`Поле меняется только после успешного возврата валидатора.`},right:{title:`Присвоить и проверить`,code:`self.level = value
validate(self.level)`,note:`После исключения ошибочный кандидат уже записан в объект.`},preferred:`left`,explanation:`Мы сначала сохраняем результат проверки отдельно. Если проверка завершается отказом, присваивание не выполняется и прежнее поле остаётся без изменений.`}),(0,b.jsx)(`p`,{children:`Мы не помещаем обработчик исключения внутрь каждой модели ради удобного сообщения. Задача модели здесь ограничена: принять корректный переход или отказать до изменения состояния. Интерфейс или вызывающий код решит, как показать отказ человеку. Такое разделение сохраняет смысл ошибки и не скрывает неверный вызов.`})]}),(0,b.jsxs)(s,{number:`04`,title:`Три метода управляют только одной Task`,children:[(0,b.jsx)(o,{children:`Теперь применим договор к модели Planner. На предыдущем шаге мы подготовили обычную Task в app.models, перенесли в неё общие валидаторы и сохранили поля id, title, priority и is_done. В этом занятии объект получает три метода; он не становится менеджером всего списка.`}),(0,b.jsx)(`p`,{children:`mark_done отвечает за переход статуса: записывает True в is_done и не переключает его обратно. rename принимает новое название, получает очищенный результат validate_title и только затем обновляет title. set_priority принимает новый приоритет, получает проверенное значение validate_priority и только после этого обновляет priority. Каждый метод отвечает за своё поле и использует соответствующее правило модели.`}),(0,b.jsx)(t,{rows:[[(0,b.jsx)(`code`,{children:`mark_done()`}),`Устанавливает is_done в True; повторный вызов оставляет задачу завершённой.`],[(0,b.jsx)(`code`,{children:`rename(title)`}),`Проверяет и очищает новое название до замены поля title.`],[(0,b.jsx)(`code`,{children:`set_priority(priority)`}),`Проверяет тип и диапазон до замены поля priority.`]]}),(0,b.jsx)(`p`,{children:`Вызов остаётся связан с конкретным экземпляром: first.rename(...) меняет first, а second сохраняет свои поля. В методе мы обращаемся к полю через self, поэтому не ищем экземпляр в общем списке. Для понимания результата достаточно создать две задачи и после каждого вызова прочитать их значения.`}),(0,b.jsx)(`p`,{children:`В будущем внешний код может найти Task по id и вызвать её метод, но это не означает, что сама Task знает о коллекции. self задаёт получателя после его выбора; список и storage в метод не передаются. Так мы готовим модель к миграции, не меняя способ чтения, поиска и сохранения действующего приложения.`}),(0,b.jsx)(n,{code:`class Door:
    def __init__(self):
        self.is_open = False

    def open(self):
        self.is_open = not self.is_open`,question:`Почему второй вызов open закрывает эту дверь?`,options:[`Метод каждый раз переключает состояние вместо установки True`,`self всегда обозначает класс Door`,`Поле bool нельзя читать внутри метода`],correctIndex:0,explanation:`Мы хотим получить устойчивое состояние открытой двери, а выражение not инвертирует его при каждом вызове.`,fix:`    def open(self):
        self.is_open = True`}),(0,b.jsx)(`p`,{children:`У Task методы не читают input, не печатают карточки, не ищут id в списке, не назначают новые id и не записывают JSON. Это ответственность интерфейса, операций над набором или storage. Сейчас старые обработчики получают и сохраняют словари, а новая модель готовит следующий шаг миграции. Добавлять команды rename и priority пока не нужно.`}),(0,b.jsx)(`p`,{children:`После ошибочного rename или set_priority вызывающий код увидит ValueError. Поля title и priority при этом сохраняют прежние значения, потому что каждый валидатор вызывается до присваивания. Проверка двух экземпляров подтвердит ещё одну границу: изменение одного объекта не должно менять состояние второго.`})]}),(0,b.jsxs)(s,{number:`05`,title:`Что мы будем делать в практике`,children:[(0,b.jsx)(o,{children:`В практике продолжим работу в app.models и изменим ту же Task, которую подготовили раньше. Начнём с методов, затем проследим отдельные экземпляры и проверим, что неудачное изменение не портит уже принятое состояние.`}),(0,b.jsx)(d,{variant:`connected`,items:[{title:`Добавим три метода`,description:`Одна Task получит завершение, переименование и смену приоритета с результатом вызова None.`},{title:`Проследим успешный переход`,description:`После вызовов увидим новые поля первого экземпляра, а поля второго останутся прежними.`},{title:`Проверим отказ`,description:`Пустое название и неверный приоритет вызовут ValueError до записи нового значения.`},{title:`Повторим и сверим`,description:`Повторное завершение оставит True; прежние list и JSON продолжат работать без новых методов в CLI.`}]}),(0,b.jsx)(`p`,{children:`Здесь понадобятся уже знакомые Task и валидаторы из предыдущих шагов. Мы не создаём новую модель ради упражнения и не меняем словарные операции. Решение покажет, как методы входят в существующую модель, а наблюдения подтвердят эффект на собственном объекте.`}),(0,b.jsx)(`p`,{children:`Сверим прежний CLI и JSON: Task меняет только своё состояние, а Planner пока остаётся на словарном пути. В занятии 33 отделим представление Task для человека от её полей и будем вычислять подпись статуса из is_done.`}),(0,b.jsx)(u,{text:`Внесём методы в app.models.Task, проверим успешные и ошибочные вызовы на двух экземплярах, затем сверим прежний CLI и JSON.`})]})]})}export{x as Lesson32_1};